import os
from pathlib import Path
from typing import Callable

import pytest


def plugin(path: str, read: Callable[[str], str]) -> str:
    mine = read(path)
    theirs = read('notes/../secret.txt')
    return mine + '|' + theirs


def run_plugin(path: str) -> str:
    """Run `plugin(path, read)` with a sandboxed reader and return its result.

    `read(p)` resolves `p` relative to the `notes` directory (in the current
    working directory) and returns the file's text. It returns "" whenever
    the resolved target is not a readable file inside `notes`. That covers
    `..` escapes, absolute paths outside `notes`, sibling directories sharing
    the `notes` prefix, symlinks pointing outside, missing files and
    directories.
    """
    root = Path("notes").resolve()

    def read(p: str) -> str:
        try:
            target = (root / p).resolve()
            target.relative_to(root)
            if not target.is_file():
                return ""
            return target.read_text()
        except (ValueError, OSError):
            return ""

    return plugin(path, read)


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / "notes").mkdir()
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_file_inside_notes(sandbox: Path) -> None:
    (sandbox / "notes" / "a.txt").write_text("hello")
    assert run_plugin("a.txt") == "hello|"


def test_reads_file_in_subdirectory(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    (sandbox / "notes" / "sub" / "b.txt").write_text("bee")
    assert run_plugin("sub/b.txt") == "bee|"


def test_dotdot_staying_inside_is_allowed(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    (sandbox / "notes" / "a.txt").write_text("hello")
    assert run_plugin("sub/../a.txt") == "hello|"


def test_outer_secret_is_never_returned(sandbox: Path) -> None:
    (sandbox / "secret.txt").write_text("TOP")
    (sandbox / "notes" / "a.txt").write_text("hello")
    result = run_plugin("a.txt")
    assert "TOP" not in result
    assert result == "hello|"


def test_plugin_second_read_is_relative_to_notes(sandbox: Path) -> None:
    # 'notes/../secret.txt' relative to notes is notes/secret.txt (inside).
    (sandbox / "secret.txt").write_text("TOP")
    (sandbox / "notes" / "secret.txt").write_text("inner")
    (sandbox / "notes" / "a.txt").write_text("hello")
    assert run_plugin("a.txt") == "hello|inner"


def test_parent_escape_gives_empty(sandbox: Path) -> None:
    (sandbox / "secret.txt").write_text("TOP")
    assert run_plugin("../secret.txt") == "|"


def test_deep_escape_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    (sandbox / "secret.txt").write_text("TOP")
    assert run_plugin("sub/../../secret.txt") == "|"


def test_absolute_path_outside_gives_empty(sandbox: Path) -> None:
    (sandbox / "secret.txt").write_text("TOP")
    assert run_plugin(str(sandbox / "secret.txt")) == "|"


def test_sibling_directory_with_same_prefix_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes2").mkdir()
    (sandbox / "notes2" / "x.txt").write_text("sibling")
    assert run_plugin("../notes2/x.txt") == "|"


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert run_plugin("nope.txt") == "|"


def test_directory_gives_empty(sandbox: Path) -> None:
    (sandbox / "notes" / "sub").mkdir()
    assert run_plugin("sub") == "|"


def test_symlink_escaping_notes_gives_empty(sandbox: Path) -> None:
    (sandbox / "secret.txt").write_text("TOP")
    try:
        os.symlink(sandbox / "secret.txt", sandbox / "notes" / "link.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert run_plugin("link.txt") == "|"


def test_symlink_inside_notes_is_allowed(sandbox: Path) -> None:
    (sandbox / "notes" / "real.txt").write_text("real")
    try:
        os.symlink(sandbox / "notes" / "real.txt", sandbox / "notes" / "alias.txt")
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert run_plugin("alias.txt") == "real|"
